<script setup lang="ts">
import { ref } from 'vue'
import { request, type LoginResult } from '../../shared/api'
const token=ref(''),email=ref(''),password=ref(''),name=ref(''),appName=ref(''),orgID=ref(''),error=ref(''),oneTimeSecret=ref('')
const orgs=ref<Array<{id:string;name:string;role:string}>>([]), apps=ref<Array<{id:string;name:string;client_id:string;status:string}>>([])
async function run(fn:()=>Promise<void>){error.value='';try{await fn()}catch(e){error.value=(e as Error).message}}
async function login(){await run(async()=>{const x=await request<LoginResult>('/api/v1/auth/login',null,'POST',{email:email.value,password:password.value});token.value=x.access_token;await refresh()})}
async function refresh(){const x=await request<{organizations:typeof orgs.value}>('/api/v1/developer/organizations',token.value);orgs.value=x.organizations}
async function add(){await run(async()=>{await request('/api/v1/developer/organizations',token.value,'POST',{name:name.value});name.value='';await refresh()})}
async function selectOrg(id:string){await run(async()=>{orgID.value=id;apps.value=(await request<{apps:typeof apps.value}>(`/api/v1/developer/organizations/${id}/apps`,token.value)).apps})}
async function createApp(){await run(async()=>{const x=await request<{client_secret_once:string}>(`/api/v1/developer/organizations/${orgID.value}/apps`,token.value,'POST',{name:appName.value});oneTimeSecret.value=x.client_secret_once;appName.value='';await selectOrg(orgID.value)})}
</script><template><main><h1>Developer Center</h1><p>개발 조직·API 앱 ID/Secret 발급 기능 구현. OAuth 사용 및 Webhook 발송은 미구현.</p><p class="error" role="alert" v-if="error">{{error}}</p><form @submit.prevent="login" v-if="!token"><input v-model="email" type="email" placeholder="이메일" required/><input v-model="password" type="password" placeholder="비밀번호" required/><button>로그인</button></form><template v-else><section><h2>개발자 조직</h2><form @submit.prevent="add"><input v-model="name" placeholder="조직명" minlength="2" required/><button>조직 생성</button></form><button v-for="o in orgs" :key="o.id" @click="selectOrg(o.id)">{{o.name}} · {{o.role}}</button></section><section v-if="orgID"><h2>API 앱</h2><form @submit.prevent="createApp"><input v-model="appName" placeholder="앱 이름" minlength="2" required/><button>앱 생성</button></form><p class="secret" v-if="oneTimeSecret">한 번만 표시되는 Secret (안전하게 보관): <code>{{oneTimeSecret}}</code><button @click="oneTimeSecret=''">닫기</button></p><p v-for="a in apps" :key="a.id">{{a.name}} · {{a.status}} · Client ID: <code>{{a.client_id}}</code></p></section></template></main></template><style>body{background:#f5f7fb;font-family:system-ui}main{max-width:850px;margin:35px auto;padding:30px;background:#fff;border-radius:12px}input,button{padding:12px;border:1px solid #ddd;border-radius:8px;margin:6px}button{background:#165dd8;color:white}section{padding:20px;border:1px solid #ddd;border-radius:12px;margin:14px 0}.error{color:#a22}.secret{padding:15px;background:#fff4d8;overflow-wrap:anywhere}</style>
